(()=>{'use strict';const nav=document.querySelector('.ops-nav');if(!nav)return;const box=document.createElement('aside');box.className='work-bar';box.hidden=true;nav.after(box);const action=document.createElement('button'),info=document.createElement('span'),pos=document.createElement('button'),link=document.createElement('a'),people=document.createElement('div'),err=document.createElement('span');people.className='active-people';err.className='work-error';err.setAttribute('role','status');pos.className='pos-toggle';pos.textContent='POS';pos.title='Крупные кнопки для сенсорного экрана';link.textContent='Смены / зарплата';link.href='/admin/workforce/';const account=document.createElement('details'),toggle=document.createElement('summary'),menu=document.createElement('div');account.className='work-account';toggle.textContent='⋯';toggle.setAttribute('aria-label','Смены и учётная запись');menu.append(link);account.append(toggle,menu);box.append(action,info,pos,account,people,err);let data,loading=false,busy=false,pending=null;const rub=n=>(n/100).toLocaleString('ru-RU')+' ₽';
 function mode(v){document.body.classList.toggle('pos-mode',v);pos.setAttribute('aria-pressed',String(v));try{localStorage.setItem('start-pos',v?'1':'0');}catch{}}try{mode(localStorage.getItem('start-pos')===null?matchMedia('(min-width:1000px)').matches:localStorage.getItem('start-pos')==='1');}catch{}pos.onclick=()=>mode(!document.body.classList.contains('pos-mode'));
 let generation=0,actionMessage='';
 function requestId(){if(crypto.randomUUID)return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return [hex.slice(0,8),hex.slice(8,12),hex.slice(12,16),hex.slice(16,20),hex.slice(20)].join('-');}
 async function request(path,body){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/admin/workforce/'+path,{cache:'no-store',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Сервер временно недоступен. Повторите действие.');}if(!r.ok)throw Object.assign(Error(d.error||'Не удалось обновить смену.'),{status:r.status});return d;}catch(e){if(e.name==='AbortError')throw Error('Нет ответа от сервера. Повторите действие: отметка не продублируется.');throw e;}finally{clearTimeout(timeout);}}
 async function refresh(){if(document.hidden||loading||busy)return;loading=true;const version=generation;try{const next=await request('current');if(busy||version!==generation)return;data=next;box.hidden=false;document.body.classList.add('desk-ready');err.textContent=actionMessage;action.disabled=false;action.textContent=data.own?'Ушёл со смены':'Я на смене';info.textContent=data.user.login+(data.own?' · с '+new Date(data.own.started_at).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}):'');people.replaceChildren();for(const p of data.active){const s=document.createElement('span');s.className='work-person';s.textContent=`${p.name} ≈ ${rub(p.salary_cents)}`;s.title=`${Math.floor(p.worked_ms/3600000)} ч ${Math.floor(p.worked_ms/60000)%60} мин на смене`;people.append(s);}people.hidden=false;if(!data.active.length)people.textContent='На смене пока никого';people.title='Предварительный заработок за сегодня. Итог после сверки кассы.';}catch(e){if(version!==generation)return;if(e.status===401&&!data){box.hidden=true;document.body.classList.remove('desk-ready');}else if(!box.hidden){err.textContent=actionMessage||e.message;if(e.status===401){data=null;action.disabled=true;err.textContent='Вход завершён. Войдите в админку снова.';}}}finally{loading=false;}}
 action.type='button';action.onclick=async()=>{if(busy||!data)return;busy=true;generation++;action.disabled=true;actionMessage='';err.classList.remove('work-success');err.textContent='Сохраняем…';try{const kind=data.own?'end':'start';if(!pending)pending={kind,body:{requestId:requestId(),...(data.own?{sessionId:data.own.id}:{})}};const d=await request(pending.kind,pending.body);data.own=pending.kind==='start'?d:null;actionMessage=pending.kind==='start'?'Вы на смене. Время прихода сохранено.':'Выход со смены сохранён.';action.textContent=data.own?'Ушёл со смены':'Я на смене';pending=null;err.classList.add('work-success');document.dispatchEvent(new Event('station-updated'));}catch(e){err.classList.remove('work-success');if(e.status&&e.status<500)pending=null;actionMessage=e.message||'Не удалось сохранить отметку. Повторите действие.';}finally{busy=false;action.disabled=false;err.textContent=actionMessage;await refresh();}};refresh();setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);document.addEventListener('station-updated',refresh);document.addEventListener('click',e=>{if(e.target.closest('#login-form button'))setTimeout(refresh,800);});})();
